window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3346e856585bb6db"]={"versions": [{"id": "FIG-3346e856585bb6db", "releases": ["R4.0.3", "R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Prozessdiagramm zur Methodik der Metamodell-Transformation, Schema-Generierung und Modellbindung innerhalb des AUTOSAR-Templates-Frameworks (AUTOSAR M2- und M1-Ebenen gemäß Generic Structure Template). Es veranschaulicht den durchgängigen Zyklus vom abstrakten Metamodell bis zum voll gebundenen Systemmodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metamodell-Artefakte (M2), Modellartefakte (M1) und Serialisierungsformate:</p>\n<ul class=\"fig-list\"><li>Metamodell-Artefakte (Rechtecke links): <code>Pure Metamodel</code>, <code>Annotated Metamodel</code> und <code>Extended Metamodel</code>.\n</li><li>Serialisierungsartefakt (Ellipse unten mittig): <code>XML Schema</code>.\n</li><li>Modell-Artefakte (Rechtecke rechts): <code>Variant rich M 1 Model</code> und <code>Bound M1 Model</code>.\n</li><li>Kanten und Beziehungen:\n<ul class=\"fig-list\"><li>Vertikale Transformationskanten links: <code>+ Variation Points</code> (Pure zu Annotated) und <code>+ Pattern resolution</code> (Annotated zu Extended).\n</li><li>Schema-Kanten: <code>creates</code> (vom Extended Metamodel zum XML Schema) und <code>defines</code> (vom XML Schema zum Variant rich M 1 Model).\n</li><li>Modellbindungskante: <code>Binding</code> (vom Variant rich M 1 Model zum Bound M1 Model).\n</li><li>Konformitätsbeziehungen (horizontale gestrichelte Linien): <code>Conforms To</code> zwischen Extended Metamodel und Variant rich M 1 Model sowie zwischen Pure Metamodel und Bound M1 Model.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess durchläuft zwei Hauptstränge mit anschließender Konvergenz:</p>\n<ol class=\"fig-list\"><li>Metamodell-Evolution: Ausgehend vom <code>Pure Metamodel</code> werden Variationspunkte annotiert (<code>+ Variation Points</code>), woraus das <code>Annotated Metamodel</code> entsteht. Durch Auflösung von Entwurfsmustern (<code>+ Pattern resolution</code>) wird das <code>Extended Metamodel</code> erzeugt.\n</li><li>Serialisierung &amp; Instanziierung: Das <code>Extended Metamodel</code> generiert (<code>creates</code>) das <code>XML Schema</code>. Dieses Schema definiert (<code>defines</code>) die syntaktische Struktur für das <code>Variant rich M 1 Model</code>.\n</li><li>Validierung &amp; Bindung: Das <code>Variant rich M 1 Model</code> steht in einer Konformitätsbeziehung (<code>Conforms To</code>) zum <code>Extended Metamodel</code>. Durch Auswertung und Bindung der Varianten (<code>Binding</code>) wird das <code>Bound M1 Model</code> erzeugt, welches wiederum konform (<code>Conforms To</code>) zum ursprünglichen <code>Pure Metamodel</code> ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert den normativen Bezugsrahmen für AUTOSAR-Modellierungs- und Binde-Werkzeuge:</p>\n<ul class=\"fig-list\"><li>Vor der Variantenbindung entspricht das instanziierte XML-Modell dem erweiterten Metamodell inklusive aller Variationspunkt-Konstrukte und Pattern-Erweiterungen.\n</li><li>Nach dem Bindungsschritt dürfen im <code>Bound M1 Model</code> keine unaufgelösten Variationspunkte oder M2-Erweiterungsstrukturen mehr wirksam sein; das Ergebnis muss exakt der Semantik des <code>Pure Metamodel</code> genügen.\n</li><li>XML-Validierungsmechanismen basieren strikt auf dem aus dem <code>Extended Metamodel</code> abgeleiteten Schema (<code>XML Schema</code>).\n</li></ul>"}, {"id": "FIG-4bcabeee61257dff", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Prozessdiagramm zur Methodik der Metamodell-Transformation, Schema-Generierung und Modellbindung innerhalb des AUTOSAR-Templates-Frameworks (AUTOSAR M2- und M1-Ebenen gemäß Generic Structure Template). Es veranschaulicht den durchgängigen Zyklus vom abstrakten Metamodell bis zum voll gebundenen Systemmodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metamodell-Artefakte (M2), Modellartefakte (M1) und Serialisierungsformate:</p>\n<ul class=\"fig-list\"><li>Metamodell-Artefakte (Rechtecke links): <code>Pure Metamodel</code>, <code>Annotated Metamodel</code> und <code>Extended Metamodel</code>.\n</li><li>Serialisierungsartefakt (Ellipse unten mittig): <code>XML Schema</code>.\n</li><li>Modell-Artefakte (Rechtecke rechts): <code>Variant rich M 1 Model</code> und <code>Bound M1 Model</code>.\n</li><li>Kanten und Beziehungen:\n<ul class=\"fig-list\"><li>Vertikale Transformationskanten links: <code>+ Variation Points</code> (Pure zu Annotated) und <code>+ Pattern resolution</code> (Annotated zu Extended).\n</li><li>Schema-Kanten: <code>creates</code> (vom Extended Metamodel zum XML Schema) und <code>defines</code> (vom XML Schema zum Variant rich M 1 Model).\n</li><li>Modellbindungskante: <code>Binding</code> (vom Variant rich M 1 Model zum Bound M1 Model).\n</li><li>Konformitätsbeziehungen (horizontale gestrichelte Linien): <code>Conforms To</code> zwischen Extended Metamodel und Variant rich M 1 Model sowie zwischen Pure Metamodel und Bound M1 Model.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess durchläuft zwei Hauptstränge mit anschließender Konvergenz:</p>\n<ol class=\"fig-list\"><li>Metamodell-Evolution: Ausgehend vom <code>Pure Metamodel</code> werden Variationspunkte annotiert (<code>+ Variation Points</code>), woraus das <code>Annotated Metamodel</code> entsteht. Durch Auflösung von Entwurfsmustern (<code>+ Pattern resolution</code>) wird das <code>Extended Metamodel</code> erzeugt.\n</li><li>Serialisierung &amp; Instanziierung: Das <code>Extended Metamodel</code> generiert (<code>creates</code>) das <code>XML Schema</code>. Dieses Schema definiert (<code>defines</code>) die syntaktische Struktur für das <code>Variant rich M 1 Model</code>.\n</li><li>Validierung &amp; Bindung: Das <code>Variant rich M 1 Model</code> steht in einer Konformitätsbeziehung (<code>Conforms To</code>) zum <code>Extended Metamodel</code>. Durch Auswertung und Bindung der Varianten (<code>Binding</code>) wird das <code>Bound M1 Model</code> erzeugt, welches wiederum konform (<code>Conforms To</code>) zum ursprünglichen <code>Pure Metamodel</code> ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert den normativen Bezugsrahmen für AUTOSAR-Modellierungs- und Binde-Werkzeuge:</p>\n<ul class=\"fig-list\"><li>Vor der Variantenbindung entspricht das instanziierte XML-Modell dem erweiterten Metamodell inklusive aller Variationspunkt-Konstrukte und Pattern-Erweiterungen.\n</li><li>Nach dem Bindungsschritt dürfen im <code>Bound M1 Model</code> keine unaufgelösten Variationspunkte oder M2-Erweiterungsstrukturen mehr wirksam sein; das Ergebnis muss exakt der Semantik des <code>Pure Metamodel</code> genügen.\n</li><li>XML-Validierungsmechanismen basieren strikt auf dem aus dem <code>Extended Metamodel</code> abgeleiteten Schema (<code>XML Schema</code>).\n</li></ul>"}], "trans": [{"from": "FIG-3346e856585bb6db", "to": "FIG-4bcabeee61257dff", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
